import{_ as l,C as e,o as d,c as i,E as a,a7 as s}from"./chunks/framework.FWlv_suP.js";const b=JSON.parse('{"title":"MetroPocket Data Deletion","description":"MetroPocket data deletion information, presented within Policy Hub.","frontmatter":{"title":"MetroPocket Data Deletion","description":"MetroPocket data deletion information, presented within Policy Hub."},"headers":[],"relativePath":"apps/metro-pocket/data-deletion.md","filePath":"apps/metro-pocket/data-deletion.md"}'),c={name:"apps/metro-pocket/data-deletion.md"};function p(m,t,h,u,k,v){const o=e("AppBreadcrumbs"),r=e("AppSubnav"),n=e("CopyStandaloneUrl");return d(),i("div",null,[a(o,{"app-id":"metro-pocket",current:"Data Deletion"}),a(r,{"app-id":"metro-pocket"}),a(n,{path:"/data-deletion/metro-pocket",label:"Copy standalone data deletion information URL","copied-label":"Data Deletion URL copied","document-name":"MetroPocket data deletion information"}),t[0]||(t[0]=s('<h1 id="delete-metropocket-data" tabindex="-1">Delete MetroPocket Data <a class="header-anchor" href="#delete-metropocket-data" aria-label="Permalink to &quot;Delete MetroPocket Data&quot;">​</a></h1><p>MetroPocket has no online account or developer-operated cloud database. App data is stored locally on your device or in your browser.</p><h2 id="remove-one-data-pack" tabindex="-1">Remove one data pack <a class="header-anchor" href="#remove-one-data-pack" aria-label="Permalink to &quot;Remove one data pack&quot;">​</a></h2><p>Open <strong>Offline Data</strong> in MetroPocket and remove the installed pack you no longer want. This deletes that pack&#39;s local copy and metadata.</p><h2 id="remove-saved-train-schedules" tabindex="-1">Remove saved train schedules <a class="header-anchor" href="#remove-saved-train-schedules" aria-label="Permalink to &quot;Remove saved train schedules&quot;">​</a></h2><p>Open <strong>Settings → Train Data</strong> and choose <strong>Delete All Train Data</strong> to remove every saved train schedule from the app. This does not remove Metro or TV packs. A Train backup exported outside the app remains in the location you chose until you delete that file separately.</p><h2 id="remove-all-local-data" tabindex="-1">Remove all local data <a class="header-anchor" href="#remove-all-local-data" aria-label="Permalink to &quot;Remove all local data&quot;">​</a></h2><ul><li><strong>Android:</strong> Clear MetroPocket&#39;s storage in Android settings or uninstall the app. Android backup and device transfer are disabled for its private data.</li><li><strong>Web/PWA:</strong> Clear site data for the MetroPocket website in your browser. This removes stored packs, preferences, train schedules, and cached app files. Uninstalling a PWA shortcut alone may not clear browser site data.</li></ul><p>Your browser may also evict stored data automatically. Removing local data does not delete support emails you sent. To request deletion of support correspondence held by the developer, email <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a>. The developer cannot remotely delete data that remains only on your device.</p>',9))])}const _=l(c,[["render",p]]);export{b as __pageData,_ as default};
